<?php
defined('ABSPATH')||exit;
class AMANAH_SEO_AI_Entity_Controller{
 private $model;private $manager;
 public function __construct($model,$manager){$this->model=$model;$this->manager=$manager;}
 public function save($input,$user_id){if(!current_user_can('amanah_manage_entity'))return new WP_Error('forbidden',__('You are not allowed to manage entities.','amanah-seo-ai'),array('status'=>403));$data=$this->sanitize_and_validate($input);if(is_wp_error($data))return $data;$data['user_id']=absint($user_id);$id=!empty($input['id'])?absint($input['id']):0;if($id){if(!$this->model->get_entity($id,$user_id,true))return new WP_Error('not_found',__('Entity not found.','amanah-seo-ai'),array('status'=>404));unset($data['user_id']);return $this->model->update_entity($id,$user_id,$data)?$id:new WP_Error('save_failed',__('Entity could not be updated.','amanah-seo-ai'));}return $this->model->create_entity($data)?:new WP_Error('save_failed',__('Entity could not be created.','amanah-seo-ai'));}
 public function delete($id,$user_id){if(!current_user_can('amanah_manage_entity'))return new WP_Error('forbidden',__('You are not allowed to delete entities.','amanah-seo-ai'),array('status'=>403));if(!$this->model->get_entity($id,$user_id,true))return new WP_Error('not_found',__('Entity not found.','amanah-seo-ai'),array('status'=>404));if($this->model->has_dependencies($id))return new WP_Error('dependency_exists',__('Entity cannot be deleted while dependent records exist.','amanah-seo-ai'),array('status'=>409));return $this->model->delete_entity($id,$user_id)?true:new WP_Error('delete_failed',__('Entity could not be deleted.','amanah-seo-ai'));}
 public function analyze($id,$user_id){if(!current_user_can('amanah_manage_entity'))return new WP_Error('forbidden',__('You are not allowed to run entity analysis.','amanah-seo-ai'),array('status'=>403));$entity=$this->model->get_entity($id,$user_id,true);if(!$entity)return new WP_Error('not_found',__('Entity not found.','amanah-seo-ai'),array('status'=>404));try{return $this->manager->analyze($entity);}catch(AMANAH_SEO_AI_AI_Exception $error){return new WP_Error('ai_analysis_failed',__('Entity analysis could not be completed.','amanah-seo-ai'),array('status'=>502));}}
 public function handle_save(){check_admin_referer('amanah_save_entity','amanah_entity_nonce');$result=$this->save(wp_unslash($_POST),get_current_user_id());$url=admin_url('admin.php?page=amanah-seo-ai');$url=add_query_arg('entity_message',rawurlencode(is_wp_error($result)?$result->get_error_message():__('Entity saved.','amanah-seo-ai')),$url);if(!is_wp_error($result))$url=add_query_arg('entity_id',absint($result),$url);wp_safe_redirect($url);exit;}
 public function handle_delete(){check_admin_referer('amanah_delete_entity','amanah_entity_nonce');$result=$this->delete(absint($_POST['id']),get_current_user_id());$url=add_query_arg('entity_message',rawurlencode(is_wp_error($result)?$result->get_error_message():__('Entity deleted.','amanah-seo-ai')),admin_url('admin.php?page=amanah-seo-ai'));wp_safe_redirect($url);exit;}
 public function handle_analyze(){check_admin_referer('amanah_analyze_entity','amanah_entity_nonce');$id=absint($_POST['id']);$result=$this->analyze($id,get_current_user_id());$url=admin_url('admin.php?page=amanah-seo-ai');if(is_wp_error($result))$url=add_query_arg('entity_message',rawurlencode($result->get_error_message()),$url);else$url=add_query_arg(array('entity_id'=>$id,'entity_analysis'=>rawurlencode(base64_encode(wp_json_encode($result)))),$url);wp_safe_redirect($url);exit;}
 public function sanitize_and_validate($input){$fields=array('entity_name','entity_type','industry','description','location','website_url','expertise','products','services','target_audience','logo_url','schema_type','status');$data=array();foreach($fields as $field){$value=isset($input[$field])?$input[$field]:'';$data[$field]=in_array($field,array('description','expertise','products','services','target_audience'),true)?sanitize_textarea_field($value):sanitize_text_field($value);}if(''===$data['entity_name']||''===$data['entity_type'])return new WP_Error('validation',__('Entity name and entity type are required.','amanah-seo-ai'),array('status'=>400));$data['status']=''===$data['status']?'active':$data['status'];return $data;}
}
